import math

class NumberFieldDemo(EasyFrame):
    def __init__(self):
        EasyFrame.__init__(self, title = "Number Field Demo")
        self.inputField = self.addIntegerField(value = 0, row = 0, column = 1)
        self.outputField = self.addFloatField(value = 0.0, row = 1, column = 1,
                                              state = "readonly")
        self.computeBtn = self.addButton(text = "Compute", row = 2, column = 0,
                                         command = self.computeSqrt)

    def computeSqrt(self):
        try:
            number = self.inputField.getNumber()
            result = math.sqrt(number)
            self.outputField.setNumber(result)
        except ValueError:
            self.messageBox(title = "ERROR",
                            message = "Input must be an integer >= 0")

win = NumberFieldDemo()
win.inputField.setText("-4")
win.computeBtn.invoke()

